import{_ as a,o as r,c as e,ag as o}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"管理组织","description":"平台超级管理员创建和维护组织，设置组织管理员，并谨慎处理停用与删除。","frontmatter":{"title":"管理组织","description":"平台超级管理员创建和维护组织，设置组织管理员，并谨慎处理停用与删除。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/organizations.md","filePath":"zh/使用指南/管理组织.md"}'),i={name:"zh/guide/organizations.md"};function l(d,t,n,s,h,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="管理组织" tabindex="-1">管理组织 <a class="header-anchor" href="#管理组织" aria-label="Permalink to &quot;管理组织&quot;">​</a></h1><p>组织用于分别管理不同团队的用户和工程。本页由<strong>平台超级管理员</strong>操作，入口是安装结果中的<strong>管理入口</strong>。普通组织账号从公共入口登录，不能代替平台账号管理组织。</p><p>全新安装只需先完成<a href="/induframe-docs/zh/installation/first-setup.html">默认组织的首次设置</a>，不一定需要另建组织。</p><h2 id="_1-打开组织管理" tabindex="-1">1. 打开组织管理 <a class="header-anchor" href="#_1-打开组织管理" aria-label="Permalink to &quot;1. 打开组织管理&quot;">​</a></h2><ol><li>打开管理入口，使用平台超级管理员账号登录。</li><li>进入 <strong>“组织管理”</strong>。</li><li>核对列表中的组织名称、管理员和启用状态。</li></ol><p>搜索框可按组织名称或代码查找。读取失败时先重试，不要把尚未加载出来的列表当成组织已经不存在。</p><h2 id="_2-创建组织" tabindex="-1">2. 创建组织 <a class="header-anchor" href="#_2-创建组织" aria-label="Permalink to &quot;2. 创建组织&quot;">​</a></h2><p>点击 <strong>“创建组织”</strong>，按页面填写：</p><table tabindex="0"><thead><tr><th>内容</th><th>怎样填写</th></tr></thead><tbody><tr><td>组织名称</td><td>填团队容易识别的名称，也会影响该组织页面上的品牌名称</td></tr><tr><td>组织代码</td><td>保存后由系统生成，不需要手工编写</td></tr><tr><td>联系方式与公司信息</td><td>按实际需要填写，有内容时注意格式正确</td></tr><tr><td>最大用户数、最大工程数</td><td>按交付安排设置，不代表可以绕过平台授权额度</td></tr><tr><td>管理员用户名</td><td>为这个组织设置专属管理员账号</td></tr><tr><td>密码、确认密码</td><td>设置相同密码，通过安全方式交付给该组织管理员</td></tr></tbody></table><p>点击 <strong>“保存”</strong>，等待成功提示，再回到列表核对新组织和管理员。创建时不使用一个通用默认密码，不要让所有组织共用同一组登录资料。</p><p>让新组织管理员从公共入口选择自己的组织并登录。若页面要求修改初始密码，先按提示完成；不要转到平台管理入口尝试使用组织账号。</p><h2 id="_3-编辑组织信息" tabindex="-1">3. 编辑组织信息 <a class="header-anchor" href="#_3-编辑组织信息" aria-label="Permalink to &quot;3. 编辑组织信息&quot;">​</a></h2><p>在对应组织行点击 <strong>“编辑”</strong>，修改后点击“保存”。返回列表再次核对，必要时刷新。</p><p>修改组织名称会影响登录选择和品牌展示；代码会按名称更新。调整用户数、工程数或登录安全选项前，先确认对现有使用者的影响。</p><p>页面提供“允许同一账号在多台设备同时登录”选项。关闭后，同一账号后一次登录会使其他设备会话失效，调整前应通知使用者。</p><p>品牌图片和公司信息按页面说明配置；不必为了开始使用平台一次填完所有展示资料。</p><h2 id="_4-组织管理员忘记密码时" tabindex="-1">4. 组织管理员忘记密码时 <a class="header-anchor" href="#_4-组织管理员忘记密码时" aria-label="Permalink to &quot;4. 组织管理员忘记密码时&quot;">​</a></h2><ol><li>找到正确的组织，核对该行管理员用户名。</li><li>点击 <strong>“重置管理员密码”</strong>。</li><li>在对话框输入新密码和确认密码。</li><li>点击 <strong>“重置密码”</strong>，等到“管理员密码已重置”。</li><li>通过安全方式把新密码交给该组织管理员，再让其从公共入口登录。</li></ol><p>重置会撤销管理员原有会话。这项操作不会把组织管理员变成平台超级管理员。</p><h2 id="_5-停用与删除要先确认" tabindex="-1">5. 停用与删除要先确认 <a class="header-anchor" href="#_5-停用与删除要先确认" aria-label="Permalink to &quot;5. 停用与删除要先确认&quot;">​</a></h2><p>停用组织会影响该组织全部用户的登录会话和工作区访问。操作前通知使用者，核对组织名称，再按页面确认；恢复使用时检查启用状态。</p><p><strong>删除组织无法撤销。</strong> 先确认相关工程、数据与备份的处理安排。页面提示仍有工程或资源依赖时，先按提示处理，不通过重复删除绕过检查。</p><p>默认组织的停用和删除受到保护，页面不会像普通组织一样提供这些操作。</p><h2 id="怎样确认操作完成" tabindex="-1">怎样确认操作完成 <a class="header-anchor" href="#怎样确认操作完成" aria-label="Permalink to &quot;怎样确认操作完成&quot;">​</a></h2><ul><li>列表中的名称、管理员和状态与本次选择一致。</li><li>保存或重置出现明确成功提示。</li><li>需要访问的组织管理员能从公共入口选择正确组织登录。</li></ul><p>操作失败时保留组织名称、时间和页面提示，联系维护人员；不要提供密码。组织内部成员的管理见<a href="/induframe-docs/zh/guide/users.html">添加和管理组织用户</a>。</p>',26)])])}const u=a(i,[["render",l]]);export{c as __pageData,u as default};
